KINDS = ('basic', 'hard', 'edge')


def trustworthy(rows):
    for kind in KINDS:
        if not any(r['kind'] == kind for r in rows):
            return 'biased'
    return 'trustworthy'

data = [
    {'kind': 'basic'},
    {'kind': 'basic'},
    {'kind': 'hard'},
    {'kind': 'edge'},
]
print(trustworthy(data))
